      var container;
    var dataKeys;
    var init = false;
    const circlesIds = ['circleTop', 'circleRight', 'circleBottom', 'circleLeft'];
    const linesIds = [ 'lineTop_Right', 'lineBottom_Right', 'lineTop_Down', 'lineBottom_Left', 'lineLeft_Right', 'lineTop_Left'];
    const bubbleIds = [ 'bubbleTop_Right', 'bubbleBottom_Right', 'bubbleTop_Bottom', 'bubbleBottom_Left', 'bubbleLeft_Right', 'bubbleTop_Left'];



 function animatebubbles(reversed, visible, id){
        const bubbleEl = container.querySelector('#' + id);
        if(!bubbleEl) return;
            bubbleEl.style.display = visible ? 'block' : 'none';
            const mpath = bubbleEl.querySelector('mpath');
        if(reversed){
            mpath.setAttribute('xlink:href', '#reversed_' + id);
        } else {
            mpath.setAttribute('xlink:href', '#' + id);
        }
    }
    self.onInit = function () {
        container = self.ctx.$container[0];
    };
    
    
    
    
    function initialize(){
        var numDataKeys = dataKeys.length;

        // circles
        for(let i=numDataKeys; i<5; i++){
            var circle = container.querySelector('#' + circlesIds[i]);
            if(circle) circle.style.display = 'none';
        }
        var text;
        var line;
        // lines and bubbles
        if (numDataKeys == 3){
            // hide lineTop_Left and bubbleTop_Left
            for (let i=2; i<linesIds.length; i++){
                 line = container.querySelector('#' + linesIds[i]);
                if(line) line.style.display = 'none';
                animatebubbles(false, false, bubbleIds[i]);
            }
            // hide text for the 4th circle
            text = container.querySelector('#' + 'grid-import');
            if(text) text.style.display = 'none';
        } else if (numDataKeys == 2){
            // hide lineTop_Left, lineBottom_Left, lineBottom_Right and bubbleTop_Left, bubbleBottom_Left, bubbleBottom_Right
            for (let i=1; i<linesIds.length; i++){
                 line = container.querySelector('#' + linesIds[i]);
                if(line) line.style.display = 'none';
                animatebubbles(false, false, bubbleIds[i]);
            }
            // hide text for the 3rd and 4th circle
            text = container.querySelector('#' + 'battery');
            if(text) text.style.display = 'none';
            text = container.querySelector('#' + 'grid-import');
            if(text) text.style.display = 'none';
        }

    }


    self.onDataUpdated = function () {
        self.ctx.$scope.data = self.ctx.defaultSubscription.data;
        dataKeys = self.ctx.$scope.data;
        if (!init) {
            initialize();
            init = true;
        }
        console.log(dataKeys[0]);
        var numDataKeys = dataKeys.length;
        var data0;
        var data1;
        var data2;
        if (numDataKeys == 3) {
             data0 = dataKeys[0];
             data1 = dataKeys[1];
             data2 = dataKeys[2];


            if (!data0 || !data1 || !data2) return;
            if (!data0.data || !data1.data || !data2.data) return;
            if (data0.data.length == 0 || data1.data.length == 0 || data2.data.length == 0) return;
            // circle top
            var circle = container.querySelector('#' + circlesIds[0]);
            if (circle) circle.innerHTML = data0.data[0][1] + ' kW';

            // circle right
            circle = container.querySelector('#' + circlesIds[1]);
            if (circle) circle.innerHTML = data1.data[0][1] + ' kW';

            // circle bottom
            circle = container.querySelector('#' + circlesIds[2]);
            if (circle) circle.innerHTML = data2.data[0][1] + ' kW';
            
        }else if (numDataKeys == 2) {
             data0 = dataKeys[0];
             data1 = dataKeys[1];
            if (!data0 || !data1) return;
            if (!data0.data || !data1.data) return;
            if (data0.data.length == 0 || data1.data.length == 0) return;

            // circle top
            var circle = container.querySelector('#' + circlesIds[0]);
            if (circle) circle.innerHTML = data0.data[0][1] + ' kW';

            // circle right
            circle = container.querySelector('#' + circlesIds[1]);
            if (circle) circle.innerHTML = data1.data[0][1] + ' kW';

            if (data0.data[0][1] >= data1.data[0][1]) {
                // animate bubbles from top to right
                animatebubbles(false, true, bubbleIds[0]);
                // hide bubbles from right to top
                animatebubbles(true, true, bubbleIds[5]);
                // hide lineTop_Right
                var line = container.querySelector('#' + linesIds[0]);
                if (line) line.style.stroke = 'blue';
            } else {
                // animate bubbles from right to top
                animatebubbles(true, true, bubbleIds[5]);
                // hide bubbles from top to right
                animatebubbles(false, true, bubbleIds[0]);
                // hide lineTop_Right
                var line = container.querySelector('#' + linesIds[0]);
                if (line) line.style.stroke = 'red';
            }

        }




    };

