descriptor.controllerScript:
self.onDataUpdated = function() {
    if (self.ctx && self.ctx.$scope && self.ctx.$scope.timeseriesTableWidget && typeof self.ctx.$scope.timeseriesTableWidget.onDataUpdated === 'function') {
        self.ctx.$scope.timeseriesTableWidget.onDataUpdated();
    }
};

self.onLatestDataUpdated = function() {
    if (self.ctx && self.ctx.$scope && self.ctx.$scope.timeseriesTableWidget && typeof self.ctx.$scope.timeseriesTableWidget.onLatestDataUpdated === 'function') {
        self.ctx.$scope.timeseriesTableWidget.onLatestDataUpdated();
    }
};

self.onEditModeChanged = function() {
    if (self.ctx && self.ctx.$scope && self.ctx.$scope.timeseriesTableWidget && typeof self.ctx.$scope.timeseriesTableWidget.onEditModeChanged === 'function') {
        self.ctx.$scope.timeseriesTableWidget.onEditModeChanged();
    }
};

self.typeParameters = function() {
    return {
        ignoreDataUpdateOnIntervalTick: true,
        hasAdditionalLatestDataKeys: true,
        supportsUnitConversion: true,
        defaultDataKeysFunction: function() {
            return [{ name: 'temperature', label: 'Temperature', type: 'timeseries', units: '°C', decimals: 0 }];
        }
    };
};

self.actionSources = function() {
    return {
        'actionCellButton': {
            name: 'widget-action.action-cell-button',
            multiple: true,
            hasShowCondition: true
        },
        'rowClick': {
            name: 'widget-action.row-click',
            multiple: false
        }
    };
};


// pomocné: extrahuje série (name + points) z widgetu (používá robustní parser)
self._getSeriesArraysFromWidget = function() {
    var widgetObj = (self.ctx && self.ctx.$scope && self.ctx.$scope.timeseriesTableWidget) ? self.ctx.$scope.timeseriesTableWidget :
                    (self.ctx && self.ctx.$scope && self.ctx.$scope.widget) ? self.ctx.$scope.widget :
                    (self.ctx && self.ctx.widget) ? self.ctx.widget : null;
    if (!widgetObj) return [];

    var raw = widgetObj.tableData || widgetObj.data || widgetObj.tableDataRaw || widgetObj.rows || widgetObj.series || null;
    var rawString = null;
    if (raw === null || raw === undefined) {
        try { rawString = JSON.stringify(widgetObj); } catch(e) { rawString = String(widgetObj); }
    } else if (typeof raw === 'string') {
        rawString = raw;
    } else {
        try { rawString = JSON.stringify(raw); } catch(e) { rawString = String(raw); }
    }

    // najdi bloky polí
    var arrayBlocks = [];
    try {
        var re = /\[\s*\[(?:[^\[\]]|\[(?:[^\[\]]|\[[^\[\]]*\])*\])*\]\s*(?:,\s*\[(?:[^\[\]]|\[(?:[^\[\]]|\[[^\[\]]*\])*\])*\]\s*)*\]/gs;
        var m;
        while ((m = re.exec(rawString)) !== null) {
            arrayBlocks.push({ text: m[0], index: m.index });
        }
    } catch (e) {}

    function findLabelBefore(idx) {
        try {
            var sub = rawString.slice(0, idx);
            var labelRe = /"pattern"\s*:\s*"([^"]+)"|"label"\s*:\s*"([^"]+)"/g;
            var last = null, lb;
            while ((lb = labelRe.exec(sub)) !== null) {
                last = lb[1] || lb[2];
            }
            return last;
        } catch (e) { return null; }
    }

    var seriesArrays = [];
    if (arrayBlocks.length > 0) {
        arrayBlocks.forEach(function(block) {
            var text = block.text;
            if ((text[0] === '"' && text[text.length-1] === '"') || (text[0] === "'" && text[text.length-1] === "'")) {
                text = text.slice(1, -1).replace(/\\"/g, '"').replace(/\\'/g, "'");
            }
            try {
                var arr = JSON.parse(text);
                var pts = [];
                if (Array.isArray(arr)) {
                    arr.forEach(function(p) {
                        if (Array.isArray(p) && p.length >= 2 && (typeof p[0] === 'number' || !isNaN(Number(p[0])))) {
                            pts.push([Number(p[0]), p[1]]);
                        }
                    });
                }
                var label = findLabelBefore(block.index) || ('series' + (seriesArrays.length+1));
                seriesArrays.push({ name: (label || '').toString(), points: pts });
            } catch (e) {
                // ignore parse error for this block
            }
        });
    } else {
        // fallback - pokus parsovat JSON a najít arrays
        try {
            var parsed = JSON.parse(rawString);
            if (parsed && parsed.columns && parsed.rows && Array.isArray(parsed.rows)) {
                // typical rows [[ts,val],...]
                if (parsed.rows.length && Array.isArray(parsed.rows[0]) && parsed.rows[0].length >= 2 && typeof parsed.rows[0][0] === 'number') {
                    var name = (parsed.columns[1] && (parsed.columns[1].label || parsed.columns[1].name)) ? (parsed.columns[1].label || parsed.columns[1].name) : 'series1';
                    seriesArrays.push({ name: name, points: parsed.rows.map(function(r){ return [r[0], r[1]]; }) });
                }
            } else {
                // hledat v objektu pole s time/value strukturou
                for (var k in parsed) {
                    if (!parsed.hasOwnProperty(k)) continue;
                    var v = parsed[k];
                    if (Array.isArray(v) && v.length && Array.isArray(v[0]) && v[0].length >= 2 && (typeof v[0][0] === 'number' || !isNaN(Number(v[0][0])))) {
                        seriesArrays.push({ name: k, points: v.map(function(p){ return [Number(p[0]), p[1]]; }) });
                    }
                }
            }
        } catch(e) {}
    }

    // ensure unique-ish names (but keep original when possible)
    var counts = {};
    seriesArrays.forEach(function(s){
        var base = s.name || 'series';
        if (!counts[base]) { counts[base]=1; s.name = base; }
        else { counts[base]++; s.name = base + '_' + counts[base]; }
    });

    return seriesArrays;
};

// upravené _createSelectionPanel: panel se otevírá nad tlačítkem dole vlevo
self._createSelectionPanel = function() {
    // pokud už existuje, jen refreshni obsah
    if (self._selectionPanel) {
        self._populateSelectionPanel();
        return;
    }

    var containerEl = (self.ctx && self.ctx.$container && self.ctx.$container.length) ? self.ctx.$container[0] :
                      (self.ctx && self.ctx.$scope && self.ctx.$scope.$element) ? self.ctx.$scope.$element[0] : null;
    if (!containerEl) return;

    // panel
    var panel = document.createElement('div');
    panel.className = 'tb-csv-selection-panel';
    Object.assign(panel.style, {
        position: 'absolute',
        // místo top/right použijeme bottom/left aby byl panel nad tlačítkem vlevo
        bottom: '46px',   // 8px tlačítko + 32px panel gap
        left: '8px',
        zIndex: '10000',
        background: 'rgba(255,255,255,0.95)',
        border: '1px solid rgba(0,0,0,0.12)',
        padding: '8px',
        boxShadow: '0 2px 6px rgba(0,0,0,0.2)',
        maxHeight: '260px',
        overflowY: 'auto',
        minWidth: '220px',
        fontSize: '13px',
        color: '#111'
    });

    // ... zbytek funkce zůstává beze změny ...
    // header s Select all a Close
    var header = document.createElement('div');
    header.style.display = 'flex';
    header.style.justifyContent = 'space-between';
    header.style.alignItems = 'center';
    header.style.marginBottom = '6px';

    var title = document.createElement('div');
    title.innerText = 'Export - vyber série';
    title.style.fontWeight = '600';
    header.appendChild(title);

    var closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.innerText = '×';
    closeBtn.title = 'Zavřít';
    Object.assign(closeBtn.style, { border: 'none', background: 'transparent', cursor: 'pointer', fontSize: '16px' });
    closeBtn.addEventListener('click', function(){ panel.style.display = 'none'; });
    header.appendChild(closeBtn);

    panel.appendChild(header);

    // container pro checkboxy
    var list = document.createElement('div');
    list.className = 'tb-csv-selection-list';
    panel.appendChild(list);

    // spodní řádek s Select all + Export
    var footer = document.createElement('div');
    footer.style.display = 'flex';
    footer.style.justifyContent = 'space-between';
    footer.style.marginTop = '8px';
    footer.style.alignItems = 'center';

    var selectAllWrap = document.createElement('label');
    selectAllWrap.style.fontSize = '13px';
    selectAllWrap.style.display = 'flex';
    selectAllWrap.style.alignItems = 'center';
    var selectAllBox = document.createElement('input');
    selectAllBox.type = 'checkbox';
    selectAllBox.style.marginRight = '6px';
    selectAllWrap.appendChild(selectAllBox);
    selectAllWrap.appendChild(document.createTextNode('Vše'));
    footer.appendChild(selectAllWrap);

    var exportBtn = document.createElement('button');
    exportBtn.type = 'button';
    exportBtn.innerText = 'Exportovat';
    Object.assign(exportBtn.style, { padding: '6px 10px', cursor: 'pointer' });
    footer.appendChild(exportBtn);

    panel.appendChild(footer);

    // přidej do containeru
    if (getComputedStyle(containerEl).position === 'static') containerEl.style.position = 'relative';
    containerEl.appendChild(panel);

    // ulož reference
    self._selectionPanel = panel;
    self._selectionListEl = list;
    self._selectAllBox = selectAllBox;

    // obsluhy
    selectAllBox.addEventListener('change', function() {
        var checks = self._selectionListEl.querySelectorAll('input[type="checkbox"].tb-csv-item');
        checks.forEach(function(ch){ ch.checked = selectAllBox.checked; ch.dispatchEvent(new Event('change')); });
    });

    exportBtn.addEventListener('click', function() {
        // zavolat export s výběrem
        self._exportUsingSelected();
        panel.style.display = 'none';
    });

    // inicialní naplnění
    self._populateSelectionPanel();
};


// naplní panel podle aktuálních sérií
self._populateSelectionPanel = function() {
    if (!self._selectionListEl) return;
    var list = self._selectionListEl;
    list.innerHTML = '';
    var series = self._getSeriesArraysFromWidget();
    // pokud nejsou série, zobraz hlášení
    if (!series || !series.length) {
        var empty = document.createElement('div');
        empty.innerText = 'Žádná série k zobrazení';
        list.appendChild(empty);
        return;
    }

    // vytvoř checkbox pro každou sérii
    series.forEach(function(s){
        var row = document.createElement('div');
        row.style.display = 'flex';
        row.style.alignItems = 'center';
        row.style.marginBottom = '4px';

        var ch = document.createElement('input');
        ch.type = 'checkbox';
        ch.className = 'tb-csv-item';
        ch.style.marginRight = '8px';
        // pokud máme uložený predvyber, použij ho
        var name = s.name || '';
        var norm = (''+name).trim();
        ch.checked = (!self._selectedSeries || self._selectedSeries.size === 0) ? true : !!self._selectedSeries.has(norm);
        ch.addEventListener('change', function() {
            if (!self._selectedSeries) self._selectedSeries = new Set();
            if (ch.checked) self._selectedSeries.add(norm);
            else self._selectedSeries.delete(norm);
            // uaktualnit selectAll box
            var all = list.querySelectorAll('input[type="checkbox"].tb-csv-item');
            var checked = list.querySelectorAll('input[type="checkbox"].tb-csv-item:checked');
            if (self._selectAllBox) self._selectAllBox.checked = (all.length === checked.length);
        });

        var lbl = document.createElement('label');
        lbl.style.flex = '1';
        lbl.style.fontSize = '13px';
        lbl.appendChild(document.createTextNode(name));

        row.appendChild(ch);
        row.appendChild(lbl);
        list.appendChild(row);

        // pokud není žádný selekt předtím, naplň set
        if (!self._selectedSeries) self._selectedSeries = new Set();
        if (ch.checked) self._selectedSeries.add(norm);
    });

    // nastavit selectAll checkbox podle aktuálního stavu
    if (self._selectAllBox) {
        var all = list.querySelectorAll('input[type="checkbox"].tb-csv-item');
        var checked = list.querySelectorAll('input[type="checkbox"].tb-csv-item:checked');
        self._selectAllBox.checked = (all.length === checked.length);
    }
};

// odstraň panel (při destroy)
self._destroySelectionPanel = function() {
    try {
        if (self._selectionPanel && self._selectionPanel.parentNode) {
            self._selectionPanel.parentNode.removeChild(self._selectionPanel);
        }
    } catch(e){}
    self._selectionPanel = null;
    self._selectionListEl = null;
    self._selectAllBox = null;
    self._selectedSeries = null;
};
// upravené onInit: tlačítko dole vlevo
self.onInit = function() {
    try {
        var containerEl = null;
        if (self.ctx && self.ctx.$container && self.ctx.$container.length) containerEl = self.ctx.$container[0];
        else if (self.ctx && self.ctx.$scope && self.ctx.$scope.$element) containerEl = self.ctx.$scope.$element[0];
        if (!containerEl) return;

        // tlačítko
        self._csvButton = document.createElement('button');
        self._csvButton.type = 'button';
        self._csvButton.innerText = 'Export CSV';
        Object.assign(self._csvButton.style, {
            position: 'absolute',
            bottom: '8px',
            left: '8px',
            zIndex: '9999',
            padding: '6px 10px',
            cursor: 'pointer'
        });
        self._csvButton.addEventListener('click', function (e) {
            e.stopPropagation();
            // otevři panel (vytvoří ho pokud chybí) a refreshni jeho obsah
            self._createSelectionPanel();
            if (self._selectionPanel) self._selectionPanel.style.display = 'block';
        });

        if (getComputedStyle(containerEl).position === 'static') containerEl.style.position = 'relative';
        containerEl.appendChild(self._csvButton);
    } catch (err) {
        console.error('CSV button init error:', err);
    }
};


// onDestroy: odstraní tlačítko i panel
self.onDestroy = function() {
    try {
        if (self._csvButton && self._csvButton.parentNode) {
            self._csvButton.parentNode.removeChild(self._csvButton);
        }
    } catch(e){}
    self._csvButton = null;
    // odstranit panel
    self._destroySelectionPanel();
};

// export - použije pouze série označené v self._selectedSeries (pokud existuje), jinak všechny
self._exportUsingSelected = function() {
    // získej série
    var series = self._getSeriesArraysFromWidget();
    if (!series || !series.length) {
        console.warn('Žádné série pro export.');
        return;
    }

    // pokud existuje selected set, použij ho, jinak všechny
    var useSet = (self._selectedSeries && self._selectedSeries.size) ? self._selectedSeries : null;
    var filtered = series.filter(function(s){
        if (!useSet) return true;
        var n = (''+s.name).trim();
        return useSet.has(n);
    });

    if (!filtered.length) {
        console.warn('Nebyla vybrána žádná série - nic se neexportuje.');
        return;
    }

    // sloučení podle timestampu
    var tsMap = {}, allTs = new Set();
    filtered.forEach(function(s) {
        s.points.forEach(function(p){
            var ts = Number(p[0]);
            if (isNaN(ts)) return;
            allTs.add(ts);
            tsMap[ts] = tsMap[ts] || {};
            tsMap[ts][s.name] = (p[1] === null || p[1] === undefined) ? '' : p[1];
        });
    });
    var allTsArr = Array.from(allTs).sort(function(a,b){return a-b;});

    // vytvoření CSV (timestamp_iso + sloupce)
    var headers = ['timestamp_iso'].concat(filtered.map(function(s){ return s.name; }));

    function escapeCsvCell(val) {
        if (val === null || val === undefined) return '';
        if (typeof val === 'object') { try { val = JSON.stringify(val); } catch(e) { val = String(val); } }
        else val = String(val);
        if (val.indexOf('"') !== -1) val = val.replace(/"/g,'""');
        if (val.indexOf(',') !== -1 || val.indexOf('\n') !== -1 || val.indexOf('\r') !== -1) return '"' + val + '"';
        return val;
    }

    var csvLines = [];
    csvLines.push(headers.map(escapeCsvCell).join(','));
    allTsArr.forEach(function(ts) {
        var iso = (new Date(Number(ts))).toISOString();
        var row = [iso];
        filtered.forEach(function(s){ row.push(tsMap[ts] && (s.name in tsMap[ts]) ? tsMap[ts][s.name] : ''); });
        csvLines.push(row.map(escapeCsvCell).join(','));
    });

    var csvContent = '\uFEFF' + csvLines.join('\r\n');
    var blob = new Blob([csvContent], {type: 'text/csv;charset=utf-8;'});
    var filename = 'timeseries_export_' + (new Date()).toISOString().replace(/[:.]/g,'-') + '.csv';
    if (window.navigator && window.navigator.msSaveOrOpenBlob) window.navigator.msSaveOrOpenBlob(blob, filename);
    else {
        var link = document.createElement('a');
        var url = URL.createObjectURL(blob);
        link.href = url; link.download = filename;
        document.body.appendChild(link);
        link.click();
        setTimeout(function(){ document.body.removeChild(link); URL.revokeObjectURL(url); }, 50);
    }

    console.log('Export dokončen, exported series:', filtered.map(function(s){return s.name;}), 'rows:', allTsArr.length);
};

