descriptor.controllerScript:
self.onInit = function() {
    self.ctx.$scope.data = self.ctx.defaultSubscription
        .data;
    self.ctx.$scope.stavTB = 1;
    self.ctx.$scope.stavEdge = 1;

    self.ctx.ulozeneHodnoty = null;
    update();
    self.onResize();
    restartTimer();
};

self.onDataUpdated = function() {
    console.log(self.ctx.defaultSubscription.data);
    update();
    self.ctx.detectChanges();
    restartTimer();
};

self.onDestroy = function() {
    stopTimer();
};

self.onResize = function() {
    var $c = self.ctx.$container;
    // PŘIDÁNO: var pro zamezení globální proměnné
    if (self.ctx.width > 500) {
        $c.find(".widget").css('display', 'none');
        $c.find(".fullScreen").css('display', 'flex');
    } else {
        $c.find(".widget").css('display', 'flex');
        $c.find(".fullScreen").css('display', 'none');
    }
}

function restartTimer() {
    stopTimer();
    self.ctx.tickInterval = setInterval(function() {
        update();
        self.ctx.detectChanges();
    }, 2000);
}

function stopTimer() {
    if (self.ctx.tickInterval) {
        clearInterval(self.ctx.tickInterval);
        self.ctx.tickInterval = null;
    }
}
function update() {
    var now = Date.now();
    var data = self.ctx.$scope.data;
    if (!data || data.length === 0) return;

    var C_OK = '#26ff23';
    var C_ERR = 'red';
    var C_OFF = 'gray';

    // Reset výchozích barev
    if (data[2]?.dataKey) data[2].dataKey.color = C_OK;
    if (data[3]?.dataKey) data[3].dataKey.color = C_OK;
    self.ctx.$scope.stavEdge = 1;

    var isBad = false;

    // --- NOVÉ: Kontrola hodnot 0 a 1 dle mappingu ---
    for (let i = 0; i <= 1; i++) {
        var val = data[i]?.data?.[0]?.[1];
        var expected = data[i]?.dataKey?.mapping;

        // Reset barvy pro 0 a 1
        if (data[i]?.dataKey) data[i].dataKey.color = C_OK;

        if (val != undefined && expected != undefined && val != expected) {
            isBad = true;
            if (data[i]?.dataKey) data[i].dataKey.color = C_ERR;
        }
    }

    // --- 1. Kontrola EDGE ---
    if (data.length > 4) {
        var connect = data[4].data[0]?.[0] || 1;
        var disconnect = data[5].data[0]?.[0] || 0;

        if (connect < disconnect) {
            isBad = true;
            self.ctx.$scope.stavEdge = 0;
            
            if(data[2]?.dataKey) data[2].dataKey.color = C_OFF;
            if(data[3]?.dataKey) data[3].dataKey.color = C_OFF;
            
            // Nulování pro výpočet
            for (let u = 2; u < 4; u++) {
                if (data[u]?.data?.[0]) data[u].data[0][1] = 0;
            }
        }
        
        // Výpočet latence
        var startIdx = (self.ctx.$scope.stavEdge === 0) ? 4 : 2;
        for (let u = startIdx; u < data.length; u++) {
            if (data[u]?.data?.[0]?.[0] != null) {
                data[u].data[0][1] = now - data[u].data[0][0];
            }
        }
    } else {
        self.ctx.$container.find(".edge").css('display', 'none');
    }

    // --- 2. Kontrola GATEWAY ---
    if (!isBad) {
        if (now - data[3]?.data[0]?.[0] > 120000) {
            isBad = true;
            if(data[3]?.dataKey) data[3].dataKey.color = C_ERR;
            if(data[2]?.dataKey) data[2].dataKey.color = C_OFF;
        }
    }

    // --- 3. Kontrola MODBUS ---
    if (!isBad) {
        if (now - data[2]?.data[0]?.[0] > 5000) {
            isBad = true;
            if(data[2]?.dataKey) data[2].dataKey.color = C_ERR;
        }
    }

    // --- Globální status ---
    if (isBad) {
        self.ctx.$scope.stavTB = 0;
        self.ctx.$scope.color = "red";
        nastavBarvuPozadi("red");
        self.ctx.$scope.celkovaKomunikace = 0;
    } else {
        self.ctx.$scope.celkovaKomunikace = 1;
        self.ctx.$scope.stavTB = 1;
        self.ctx.$scope.color = C_OK;
        nastavBarvuPozadi("none");

        if (self.ctx.ulozeneHodnoty !== null) {
             self.ctx.ulozeneHodnoty = null;
        }
    }
    
    
    self.ctx.detectChanges();
}
function nastavBarvuPozadi(barva) {
    var el = document.getElementById("gridster-background");
    if (el) el.style.background = (barva === 'none') ? '' :
        barva;
}

