descriptor.controllerScript:
self.onInit = function() {
    var listElement = document.getElementById('notifList');
    var unreadCb = document.getElementById('unreadOnlyCb');
    var pageInfo = document.getElementById('pageInfo');
    var refreshTimer; 
    
    var currentPage = 0;
    var pageSize = 10;
    var hasNext = false;

    document.getElementById('refreshBtn').onclick = function() { reload(); };
    document.getElementById('markAllBtn').onclick = function() { markAllAsRead(); };
    unreadCb.onchange = function() { reload(); };
    
    document.getElementById('prevBtn').onclick = function() { 
        if (currentPage > 0) { currentPage--; fetchNotifs(); }
    };
    document.getElementById('nextBtn').onclick = function() { 
        if (hasNext) { currentPage++; fetchNotifs(); }
    };

    // Auto-refresh každých 60s
    refreshTimer = setInterval(function() {
        fetchNotifs();
    }, 60000);

    function reload() {
        currentPage = 0;
        fetchNotifs();
    }

    function fetchNotifs() {
        var params = {
            pageSize: pageSize,
            page: currentPage,
            sortProperty: 'createdTime',
            sortOrder: 'DESC',
            unreadOnly: unreadCb.checked 
        };
        
        var queryString = Object.keys(params)
            .map(key => key + '=' + params[key])
            .join('&');

        self.ctx.http.get('/api/notifications?' + queryString).subscribe(
            function(response) {
                renderList(response.data);
                updatePagination(response);
            },
            function(err) {
                console.error(err);
            }
        );
    }
    
    function markAllAsRead() {
        if(!confirm("Označit vše jako přečtené?")) return;
        self.ctx.http.put('/api/notifications/read').subscribe(
            function() { reload(); },
            function(err) { alert("Chyba."); }
        );
    }

    function renderList(items) {
        listElement.innerHTML = '';
        if (!items || items.length === 0) {
            listElement.innerHTML = '<div style="padding:20px; text-align:center; color:#999">Žádné notifikace</div>';
            return;
        }

        items.forEach(item => {
            var li = document.createElement('li');
            var isUnread = item.status !== 'READ';
            li.className = 'notif-item' + (isUnread ? ' unread' : '');
            
            var date = new Date(item.createdTime).toLocaleString();
            var subject = item.subject || 'Upozornění';
            var text = item.text || '';

            li.innerHTML = `
                <div class="notif-subject">${subject}</div>
                <div class="notif-text">${text}</div>
                <div class="notif-time">${date}</div>
            `;

            if (isUnread) {
                var btn = document.createElement('button');
                btn.className = 'read-btn';
                btn.innerHTML = '✓';
                btn.title = 'Přečíst';
                btn.onclick = function(e) {
                    e.stopPropagation();
                    markOneRead(item.id.id, li, btn);
                };
                li.appendChild(btn);
            }
            listElement.appendChild(li);
        });
        self.ctx.detectChanges();
    }
    
    function markOneRead(id, li, btn) {
        self.ctx.http.put('/api/notification/' + id + '/read').subscribe(
            function() {
                li.classList.remove('unread');
                btn.remove();
                if (unreadCb.checked) li.style.display = 'none';
            },
            function(err) { console.error(err); }
        );
    }
    
    function updatePagination(data) {
        hasNext = data.hasNext;
        pageInfo.innerText = (currentPage + 1) + ' / ' + (data.totalPages || 1);
        document.getElementById('prevBtn').disabled = (currentPage === 0);
        document.getElementById('nextBtn').disabled = !hasNext;
        document.getElementById('pagination').style.display = data.totalPages > 1 ? 'block' : 'none';
    }

    fetchNotifs();
    
    // Uložení reference pro onDestroy
    self.refreshTimer = refreshTimer;
}

self.onDestroy = function() {
    if (self.refreshTimer) {
        clearInterval(self.refreshTimer);
    }
}

