self.onInit = function() {
    var scope = self.ctx.$scope;
    var updateInterval;

    // --- Function to generate and update random time window ---
    function updateRandomTimeWindow() {
        var now = new Date().getTime();
        var randomDaysAgo = Math.floor(Math.random() * 30) + 1; // 1 to 30 days
        var startOfDay = new Date(now);
        startOfDay.setHours(0, 0, 0, 0);
        var randomStartMs = startOfDay.getTime() - (randomDaysAgo * 24 * 60 * 60 * 1000);

        scope.myInitialTimeWindow = {
            startTs: randomStartMs,
            endTs: new Date(now).getTime()
        };
        
        console.log('JS Controller: Aktualizuji myInitialTimeWindow (náhodná data pro test Inputu)...');
        
        // This is crucial to tell ThingsBoard to update the view
        self.ctx.detectChanges();
    }

    // Set an initial value
    scope.myInitialTimeWindow = {};
    updateRandomTimeWindow(); // Call once to initialize

    // Set interval to update every 5 seconds (for testing Input reactivity)
    //updateInterval = setInterval(updateRandomTimeWindow, 5000);

    // Function to handle the output event from the component
    scope.onTimeWindowChange = function(newTimeWindow) {
        console.log('%cParent (widget) received change from component via standard event:', 'color: green; font-weight: bold;', newTimeWindow);
        // Update the bound variable in the parent's scope
        scope.myInitialTimeWindow = newTimeWindow;
        // This will automatically trigger change detection
        self.ctx.detectChanges(); // Ensure ThingsBoard updates if needed
    };

    self.onDestroy = function() {
        if (updateInterval) {
            clearInterval(updateInterval);
        }
    };
};

