self.onInit = function() {
    var $scope = self.ctx.$scope;
    
    // 1. Definujeme logiku funkce do proměnné (aby byla dostupná hned)
    var handleStatusPing = function(isOk) {
        // console.log("Status Ping:", isOk); // Odkomentuj pro debugování

        // Broadcast statusu ostatním widgetům
        if (self.ctx.broadcastService) {
            self.ctx.broadcastService.broadcast('WIDGET_STATUS', {
                isOk: isOk
            });
        }

        // Nastavení proměnných pro UI
        if (!isOk) {
            $scope.stavTB = 0;
            $scope.color = "red";
        } else {
            $scope.stavTB = 1;
            $scope.color = "green";
            
            // Reset uložené hodnoty
            if (self.ctx.ulozeneHodnoty !== undefined && self.ctx.ulozeneHodnoty !== null) {
                self.ctx.ulozeneHodnoty = null;
            }
        }

        // DŮLEŽITÉ: Vynutit překreslení UI
        self.ctx.detectChanges();
    };

    // 2. PŘIŘAZENÍ (Dvojitá pojistka)
    // Pro případ, že HTML volá: (statusPing)="onStatusPing($event)"
    $scope.onStatusPing = handleStatusPing;
    
    // Pro případ, že HTML volá: (statusPing)="ctx.onStatusPing($event)"
    // nebo pokud komponenta tb-miikue-communication volá ctx.onStatusPing() interně
    self.ctx.onStatusPing = handleStatusPing;

    // 3. Zbytek inicializace
    $scope.ctx = self.ctx;
    $scope.data = self.ctx.defaultSubscription.data;

    // Načtení služby
    self.ctx.broadcastService = $scope.$injector.get(self.ctx.servicesMap.get('broadcastService'));    

    self.onResize();
};

self.onResize = function() {
    // Bezpečnější kontrola existence dashboard objektu
    if (self.ctx.dashboard) {
        self.ctx.$scope.fullscreen = self.ctx.dashboard.isWidgetExpanded;
    }
    self.ctx.detectChanges();
};

self.onDataUpdated = function() {
    if (self.ctx.$scope.miikueCommunicationWidget) {
        self.ctx.$scope.miikueCommunicationWidget.onDataUpdated();
    }
    self.ctx.detectChanges();
};

self.onDestroy = function() {
    // Cleanup
};

self.onInit = function() {
    var $scope = self.ctx.$scope;
    $scope.data = self.ctx.defaultSubscription.data;
    $scope.isOk = true;
    $scope.ctx = self.ctx;

    self.onResize();

    self.ctx.broadcastService = $scope.$injector.get(
        self.ctx.servicesMap.get('broadcastService')
    );

    // Ulozeni reference na listener
    self.statusListener = self.ctx.broadcastService.on('WIDGET_STATUS', (event, data) => {
        $scope.isOk = data[0].isOk;
        self.ctx.detectChanges();

        if ($scope.miikueStavyWidget) {
            $scope.miikueStavyWidget.onDataUpdated();
        }
    });
};

self.onResize = function() {
    self.ctx.$scope.fullscreen = self.ctx.dashboard && self.ctx.dashboard.isWidgetExpanded;
    self.ctx.detectChanges();
};

self.onDataUpdated = function() {
    self.ctx.detectChanges();
    if (self.ctx.$scope.miikueStavyWidget) {
        self.ctx.$scope.miikueStavyWidget.onDataUpdated();
    }
};

self.onDestroy = function() {
    // Nutny cleanup
    if (self.statusListener) {
        // Predpokladam, ze .on() vraci 'deregister' funkci (standard v Angular/TB)
        // Pokud vraci objekt, pouzij self.statusListener.unsubscribe();
        (typeof self.statusListener === 'function') 
            ? self.statusListener() 
            : self.statusListener.unsubscribe && self.statusListener.unsubscribe();
    }
};

self.onDataUpdated = function() {
    self.ctx.$scope.miikueChartLineWidget.onDataUpdated();

};


self.onLatestDataUpdated = function() {
    self.ctx.$scope.timeSeriesChartWidget.onLatestDataUpdated();
}

self.onResize = function(){
    self.ctx.$scope.fullscreen = self.ctx.dashboard && self.ctx.dashboard.isWidgetExpanded;
}

self.onDestroy = function() {
    // Cleanup logic if needed
};

